/**
 * README screenshots, regenerated by .github/workflows/visual-docs.yml.
 *
 *   npx playwright test -c playwright.visual-docs.config.ts
 *
 * DB-free: every /api call is mocked (same approach as e2e/mocked) with fixed
 * demo data and a frozen clock, so output only changes when the UI does and the
 * bot PR doesn't churn on "3 days ago" labels. Writes docs/screenshots/*.png.
 */
import { test, expect } from '@playwright/test';
import type { BrowserContext, Page } from '@playwright/test';
import { encode } from 'next-auth/jwt';

const OUT = 'docs/screenshots';
const NOW = new Date('2026-09-25T12:00:00Z');

