async function mockApi(target: Page | BrowserContext): Promise<void> {
  const json = (body: unknown) => ({ status: 200, contentType: 'application/json', body: JSON.stringify(body) });
  await target.route('**/api/repos?*', (route) => route.fulfill(json(REPOS)));
  await target.route('**/api/repo-details/*/trend', (route) => route.fulfill(json({ success: true, snapshots: [] })));
  await target.route('**/api/repo-details/*', (route) => route.fulfill(json(DETAILS)));
  await target.route('**/api/dependencies', (route) => route.fulfill(json({ success: true, nodes: [], edges: [] })));
  await target.route('**/api/gemini-status', (route) => route.fulfill(json({ status: 'ok' })));
  await target.route('**/api/github-rate-limit', (route) => route.fulfill(json({ core: { remaining: 5000, limit: 5000, reset: 0 } })));
  await target.route('**/api/pmo/overview', (route) => route.fulfill(json(PMO)));
}

async function signedInContext(page: Page): Promise<void> {
  const secret = process.env.NEXTAUTH_SECRET;
  if (!secret) throw new Error('NEXTAUTH_SECRET must be set for the visual-docs server and tests');
  const value = await encode({
    token: { name: 'Demo Owner', email: 'demo@example.com', sub: 'demo-owner' },
    secret,
    salt: 'authjs.session-token',
  });
  await page.context().addCookies([{ name: 'authjs.session-token', value, domain: 'localhost', path: '/' }]);
}

test.use({ viewport: { width: 1280, height: 800 }, colorScheme: 'dark' });

test.beforeEach(async ({ page }) => {
  await page.clock.setFixedTime(NOW);
  await mockApi(page);
  // `next dev` renders its dev-tools badge in a <nextjs-portal>; keep it out of the docs.
  await page.addInitScript(() => {
    document.addEventListener('DOMContentLoaded', () => {
      const style = document.createElement('style');
      style.textContent = 'nextjs-portal { display: none !important; }';
      document.head.appendChild(style);
    });
  });
});

test('dashboard', async ({ page }) => {
  await page.goto('/');
  // Scoped to the desktop table: the hidden mobile cards render the same names.
  await expect(page.locator('table tbody')).toContainText('agent-board', { timeout: 30_000 });
  await page.screenshot({ path: `${OUT}/dashboard.png` });
});

test('repo details', async ({ page }) => {
  await page.goto('/');
  // Sorted by name, so the vigil row is last; expand it via its description cell.
  const row = page.locator('table tbody tr', { hasText: 'Portfolio health dashboard' });
  await expect(row).toBeVisible({ timeout: 30_000 });
  await row.locator('td').nth(1).click();
  await expect(page.getByRole('heading', { name: 'Repository Stats' })).toBeVisible({ timeout: 15_000 });
  await page.getByRole('heading', { name: 'Repository Stats' }).scrollIntoViewIfNeeded();
  await page.screenshot({ path: `${OUT}/repo-details.png` });
});

test('pmo', async ({ page }) => {
  await signedInContext(page);
  await page.goto('/pmo');
  await expect(page.getByText('Portfolio Pipeline')).toBeVisible();
  await page.screenshot({ path: `${OUT}/pmo.png` });
});
